!function(){"use strict";const t=new class{constructor(t){this.dropSelector=t,this.activeClass="nav-active",this.openerSelector=".nav-opener"}init(){this.handleEvents()}handleEvents(){document.body.addEventListener("click",t=>{const e=t.target.closest(this.openerSelector),s=t.target.closest(this.dropSelector);if(e)return t.preventDefault(),void this.toggle();s||this.close()})}toggle(){document.body.classList.toggle(this.activeClass)}close(){document.body.classList.remove(this.activeClass)}}(".drop");document.addEventListener("DOMContentLoaded",()=>{t.init()})}();